import { IObstacle } from '../../Obstacles/@types/obstacles.types';

export interface IMapType {
  id: number;
  name: string;
  isElliptical: boolean;
  key: string;
  maxZoom: number;
  minZoom: number;
  subdomains: string;
  tileUrlTmpl: string;
}

export interface IBaseRoute {
  id: number;
  name: string;
  description: string;
  bounds: [[number, number], [number, number]];
  id_type: number;
  previewImg: string;
  dateCreate: string;
  author: {
    id: number;
    name: string;
    photo: string;
  };
}

export enum RouteObjectType {
  Point = 1,
  Line = 2,
}

export interface IBaseRouteObject {
  id: number;
  name: string;
  description: string;
  is_in_distance: boolean;
  order: number;
  type: RouteObjectType;

  dateCreate: string;
  author?: {
    id: number;
    name: string;
    photo: string;
  };
  dateUpdate: string | null;
  updater: null | {
    id: number;
    name: string;
    photo: string;
  };
}

export interface IBaseRouteObjectPoint extends IBaseRouteObject {
  type: RouteObjectType.Point;
  coordinates: [number, number] | [number, number, number];
  color?: string;
  obstacle: IObstacle | null;
}

export interface IBaseRouteObjectLine extends IBaseRouteObject {
  type: RouteObjectType.Line;
  points: Array<[number, number, number] | [number, number]>;
  distance: number;
  color?: string;
  width: number;
  opacity: number;
}

export type IRouteObject = IBaseRouteObjectLine | IBaseRouteObjectPoint;

export default {};
