import { lttbGPS } from '@helpers/gpsHelper';
import {
  getGpxDataSequencesFromStrings,
  getStringsFromGpxDataSequences,
} from '@helpers/gpxDecode.helper';

import {
  IObstacleDTO,
  ObstacleCategoryDTO,
  ObstacleTypeDTO,
} from '../../Obstacles/@types/obstacles.dto.types';
import {
  IBaseRouteDTO,
  IMapTypeDTO,
  IRouteObjectDTO,
  IUpdateRouteLineDTO,
  IUpdateRouteObjectBaseDTO,
  IUpdateRoutePointDTO,
} from '../@types/DTO/routes.dto.types';
import {
  IBaseRoute,
  IBaseRouteObject,
  IBaseRouteObjectLine,
  IBaseRouteObjectPoint,
  IMapType,
  IRouteObject,
  RouteObjectType,
} from '../@types/routes.types';
import { mapObstacleDTOToFront } from './../../Obstacles/@mappers/obstacles.toFront.mapper';

export const mapMapTypeToFront = (backData: IMapTypeDTO): IMapType => {
  return {
    id: +backData.id,
    name: backData.name,
    isElliptical: !!backData.isElliptical,
    key: backData.key,
    maxZoom: +backData.maxZoom,
    minZoom: +backData.minZoom,
    subdomains: backData.subdomains,
    tileUrlTmpl: backData.tileUrlTmpl,
  };
};

export const mapBaseRouteToFront = (backData: IBaseRouteDTO): IBaseRoute => {
  return {
    id: +backData.id,
    name: backData.name,
    description: backData.desc,
    bounds: JSON.parse(backData.bounds),
    id_type: +backData.id_type,
    previewImg: backData.preview_img,
    dateCreate: backData.date_create,
    author: {
      id: +backData.author_id,
      name: backData.author_name,
      photo: backData.author_photo,
    },
  };
};

const mapRouteObjectBaseToFront = (backData: IRouteObjectDTO): IBaseRouteObject => {
  return {
    id: +backData.id,
    name: backData.name,
    description: backData.desc,
    is_in_distance: backData.is_in_distance === '1',
    type: backData.id_typeobject === '1' ? RouteObjectType.Point : RouteObjectType.Line,
    dateCreate: backData.date_create,
    order: +backData.ord,
    author: {
      id: +backData.creator_id,
      name: backData.creator_name,
      photo: backData.creator_photo,
    },
    dateUpdate: backData.date_last_modif ? backData.date_last_modif : null,
    updater: backData.date_last_modif
      ? {
          id: +backData.id_editor,
          name: backData.editor_name,
          photo: backData.editor_photo,
        }
      : null,
  };
};

const mapRouteObjectObstacleToIObstacleDTO = (backData: IRouteObjectDTO): IObstacleDTO => {
  return {
    id: backData.obstacle_id ?? '', //string;
    name: backData.obstacle_name ?? '', //string;
    description: backData.obstacle_description ?? '', //string;
    lat: backData.obstacle_lat ?? '', //string;
    lon: backData.obstacle_lon ?? '', //string;
    altitude: backData.obstacle_altitude ?? '', //string;
    link: backData.obstacle_link ?? '', //string;
    comment: backData.obstacle_comment ?? '', //string;
    type: (backData.obstacle_type ?? 'poi') as ObstacleTypeDTO,
    category: (backData.obstacle_category ?? 'no') as ObstacleCategoryDTO,
    created_at: backData.obstacle_created_at ?? '', //string;
    creator_id: backData.obstacle_creator_id ?? '', //string;
    creator_name: backData.obstacle_creator_id ?? '', //string;
    updated_at: '', //string;
    updator_id: '', //string;
    updator_name: '', //string;
    geo_region_id: backData.obstacle_id_geo_region ?? '', //string;
    geo_region_name: backData.obstacle_id_geo_region ?? '', //string;
  };
};

const mapRouteObjectPointToFront = (backData: IRouteObjectDTO): IBaseRouteObjectPoint => {
  return {
    ...mapRouteObjectBaseToFront(backData),
    type: RouteObjectType.Point,
    coordinates: JSON.parse(backData.coordinates),
    color: backData.stroke_color,
    obstacle: backData.obstacle_id
      ? mapObstacleDTOToFront(mapRouteObjectObstacleToIObstacleDTO(backData))
      : null, //@todo obstacle
  };
};

const mapRouteObjectLineToFront = (backData: IRouteObjectDTO): IBaseRouteObjectLine => {
  const points: ([number, number] | [number, number, number])[] = [];
  const { latitudes, longitudes, altitudes } = getGpxDataSequencesFromStrings(backData);
  if (latitudes && longitudes) {
    latitudes.forEach((lat, i) => {
      const point: [number, number] | [number, number, number] = [lat, longitudes[i]];
      if (altitudes?.[i]) point.push(altitudes[i]);

      points.push(point);
    });
  } else if (backData.coordinates?.length) {
    const coords = JSON.parse(backData.coordinates) ?? [];
    points.push(...coords);
  } else {
    console.warn(
      `Для RouteObject #${backData.id} ${backData.name} отсутствует последовательность координат`,
    );
  }

  return {
    ...mapRouteObjectBaseToFront(backData),
    type: RouteObjectType.Line,
    points,
    distance: +backData.distance,
    color: backData.stroke_color,
    width: +backData.stroke_width,
    opacity: +backData.stroke_opacity,
  };
};

export const mapRouteObjectToFront = (backData: IRouteObjectDTO): IRouteObject => {
  if (backData.id_typeobject === '1') {
    return mapRouteObjectPointToFront(backData);
  } else {
    return mapRouteObjectLineToFront(backData);
  }
};

const mapFrontRouteObjectBaseDataToBack = (
  frontData: IBaseRouteObject,
  id_route: number,
): IUpdateRouteObjectBaseDTO => {
  return {
    id: frontData.id,
    name: frontData.name,
    desc: frontData.description,
    is_in_distance: frontData.is_in_distance ? 1 : 0,
    id_type: frontData.type === RouteObjectType.Point ? 1 : 2,
    stroke_color: '#006699',
    stroke_width: 0,
    stroke_opacity: 0,
    icon_url: null,
    distance: 0,
    id_route,
    id_mountain_pass: null,
  };
};

export const mapFrontPointToBackUpdate = (
  frontData: IBaseRouteObjectPoint,
  id_route: number,
): IUpdateRoutePointDTO => {
  return {
    ...mapFrontRouteObjectBaseDataToBack(frontData, id_route),
    id_type: 1,
    id_mountain_pass: frontData.obstacle?.id ?? null,
    id_obstacle: frontData.obstacle?.id ?? null,
    stroke_width: 0,
    stroke_opacity: 0,
    distance: 0,
    stroke_color: frontData.color || '#006699',
    coordinates: JSON.stringify(frontData.coordinates),
  };
};

export const mapFrontLineToBackUpdate = (
  frontData: IBaseRouteObjectLine,
  id_route: number,
): IUpdateRouteLineDTO => {
  return {
    ...mapFrontRouteObjectBaseDataToBack(frontData, id_route),
    id_type: 2,
    id_mountain_pass: null,
    distance: frontData.distance,
    stroke_color: frontData.color || '#006699',
    stroke_width: frontData.width,
    stroke_opacity: frontData.opacity,
    ...getStringsFromGpxDataSequences({
      latitudes: frontData.points.map((p) => p[0]),
      longitudes: frontData.points.map((p) => p[1]),
      altitudes: frontData.points.map((p) => p[2] ?? 0),
    }),
    coordinates_preview: JSON.stringify(
      lttbGPS(
        frontData.points.map((p) => [p[0], p[1]]),
        Math.round(frontData.points.length * 0.05),
      ),
    ),
  };
};
