export const addRoutePointAsync = async (
  id_route: number,
  coordinates: [number, number, number | undefined],
  name = 'Точка',
  color = 'red',
  id_obstacle: number | null = null,
): Promise<IRouteObject> => {
  const rawData = await post<{ data: IRouteObjectDTO }, IAddRoutePointDTO>(
    '/ajax/routes/map_object_add.php',
    {
      id_route,
      id_type: 1,
      coordinates: JSON.stringify(coordinates),
      name,
      stroke_color: color,
      id_obstacle,
    },
  ).then(handleApiError);
  return mapRouteObjectToFront(rawData.data);
};

export const addRouteLineAsync = async (
  id_route: number,
  coordinates: Array<[number, number, number] | [number, number]>,
  {
    name,
    color,
    width,
    opacity_pct,
    distance,
  }: { name: string; color: string; width: number; opacity_pct: number; distance: number },
): Promise<IRouteObject> => {
  const rawData = await post<{ data: IRouteObjectDTO }, IAddRouteLineDTO>(
    '/ajax/routes/map_object_add.php',
    {
      id_route,
      id_type: 2,
      ...getStringsFromGpxDataSequences({
        latitudes: coordinates.map((p) => p[0]),
        longitudes: coordinates.map((p) => p[1]),
        altitudes: coordinates.map((p) => p[2] ?? 0),
      }),
      coordinates_preview: JSON.stringify(
        lttbGPS(
          coordinates.map((p) => [p[0], p[1]]),
          Math.round(coordinates.length * 0.05),
        ),
      ),
      name,
      stroke_color: color,
      stroke_width: width,
      stroke_opacity: opacity_pct,
      distance,
    },
  ).then(handleApiError);
  return mapRouteObjectToFront(rawData.data);
};

