export const getCoordsWithElevationsAsync = async (
  coordinates: CoordsWithOptionalEle[],
): Promise<[number, number, number][]> => {
  const locations = coordinates
    .map(([latitude, longitude]) => [latitude, longitude].join(','))
    .join('|');
  let rawData;
  try {
    rawData = await get(
      '/ajax/routes/external/elevation.php',
      { locations },
      { signal: AbortSignal.timeout(5000) },
    ).then(handleApiError);
    return (rawData.results as Record<string, number>[]).map((d) => [
      d.latitude,
      d.longitude,
      d.elevation,
    ]);
  } catch (e) {
    console.error(e as Error);
    rawData = await get('/ajax/routes/external/elevation.php', { locations, variant: 1 }).then(
      handleApiError,
    );
    return (rawData.results as { elevation: number; location: { lat: number; lng: number } }[]).map(
      (d) => [d.location.lat, d.location.lng, d.elevation],
    );
  }
};

