export const enrichAltitudesIfNecessary = async (
  coordinates: CoordsWithOptionalEle[],
): Promise<[number, number, number][]> => {
  const indexes: number[] = [];
  const coordsWithoutAltitude = coordinates.filter(([_, __, alt], i) => {
    const hasAlt = Number.isFinite(alt);

    if (!hasAlt) indexes.push(i); // Запоминаем индексы в оригинальном массиве чтобы потом инжектить туда высоты

    return !hasAlt;
  });

  if (!coordsWithoutAltitude.length) return coordinates as [number, number, number][];

  try {
    const coordsWithAlt = await getCoordsWithElevationsAsync(coordsWithoutAltitude);

    return coordinates.map((coord, i) => {
      const ind = indexes.findIndex((ii) => ii === i);
      if (ind >= 0) {
        return coordsWithAlt[ind];
      }
      return coord as [number, number, number];
    });
  } catch (e) {
    notificationHelper.warn('Не удалось рассчитать высоты для трека' + (e as Error).message);
  }
};

