export interface IRouteListItem {
  id: number;
  name: string;
  description: string;
  preview: string;
  distance: number;
  dateCreate: Date;
  author: IUser;
  editors: IUser[];
  hikingList: IBaseHiking[];
  regions: IRegion[];
}

export const getAllRoutes = async (region?: number): Promise<IRouteListItem[]> => {
  const raw = await get<IRouteListItemDTO[]>('/ajax/routes/map_list.php', { region }).then(
    handleApiError,
  );
  return raw.map((b: IRouteListItemDTO) => {
    return {
      id: +b.id,
      name: b.name,
      description: b.desc,
      preview: b.preview_img,
      hikingList:
        b.hiking?.split(',').map((str) => {
          const [id, name, ava, start, finish] = str.split('œ');
          return {
            id: +id,
            name,
            ava,
            start: new Date(start),
            finish: new Date(finish),
          };
        }) ?? [],
      distance: +b.distance,
      dateCreate: new Date(b.date_create),
      editors:
        b.editors?.split(',').map((str) => {
          const [id, name, surname, photo] = str.split('œ');
          return {
            id: +id,
            name,
            surname,
            photo,
          } satisfies IUser;
        }) ?? [],
      author: {
        id: b.id_author,
        name: b.author_name,
        surname: b.author_surname,
        photo: b.author_photo,
      },
      regions:
        b.regions?.split(',').map((r) => {
          const [id, name] = r.split('œ');
          return { id, name };
        }) ?? [],
    };
  });
};

